// Enthaelt: LOCATIONS, BELL_TOWERS, MAIN_QUESTS, KLIFF_STAMINA, KLIFF_SPIRIT, KLIFF_HEALTH, DAMIANE_SKILLS, OONGKA_SKILLS, WATCH_AND_LEARN, BOSS_IMGS, BOSS_IMGS_CDN, BOSS_ALT_IMGS, SKILL_IMGS, SKILL_IMGS_BY_CHAR, WEAPON_IMGS, FEX_IMG_PREFIX
const LOCATIONS=[
  {name:"Shadow's Whisper Cave",region:"Hernand",type:"Alchemy Station",desc:"Höhle in einer Felsspalte unter den Drei-Heiligen-Fällen, nördlich von Hernand-Stadt. Witch's Cauldron + Palmar-Pill-Formel frei auf dem Tisch (bei der Hexe Sylvia, Quest 'Verfeinerte Kraft', ab Kap. 3)."},
  {name:"Karin Quarry",region:"Hernand",type:"Dungeon / Farm",desc:"Steinbruch der Roberts-Familie. Marnis Steinbruchmaschine Boss (Fraktionsquest Haus Roberts: Ländereien im Aufruhr, Mission Gestohlener Steinbruch; Belohnung Bergbau-Knöchelbohrer + Karte der Goldader). Weitere Mission derselben Quest: Versiegelt im Stein (Belohnung Schlüssel zum Kransteuerungsraum). Reihenfolge der Quest Ländereien im Aufruhr laut questlog: Die erste Prüfung des Vertrauens, Der besorgte Graf, Gestohlener Steinbruch (Blut-Banditen besetzen den Steinbruch), Versiegelt im Stein, Die Ehre des Grafen."},
  {name:"Hernand Town",region:"Hernand",type:"Stadt",desc:"Hub mit Blacksmith Turnali, Equipment-Vendor Rhett, Fleischerladen Renee, Provisioner, Contribution Shop."},
  {name:"Witchwoods",region:"Hernand (SW)",type:"Witch Location",desc:"Elowens Haus ('Hexenhaus' in den Alfonso-Ländereien von Hernand; laut questlog ein Haus mit blumengeschmücktem Garten und Springbrunnen, in dem Essen und eine Teekanne stets auf dem Tisch stehen). Laut game8 hält die Quest 'Hexe der Weisheit' Tanya als Geisel in einem von Banditen besetzten Haus in den Witchwoods; den Einstieg durchs Dachfenster nennt der Hauptquest-Eintrag 'Das fehlende Siegel' (Kap. 5) für die Hexenhütte östlich des Scholarship Institute — ob beides dasselbe Haus ist, ist nicht belegt. In der Nähe liegt das Sanktum der Absolution (laut game8 zwischen den Witchwoods und dem Sonnenuntergangstal); das Sanktum der Mäßigung liegt dagegen im Pororin-Wald."},
  {name:"White Wastes Sanctuary",region:"Pailune (NW)",type:"Unique Weapon",desc:"Darkbringer Greatsword: Skelett-Krater, Schwert aus Riesenskeletts Maul ziehen. Kein Boss nötig."},
  {name:"Frostveiled Castle Ruins",region:"Pailune (N)",type:"Unique Weapon",desc:"Eid des toten Königs in der Citadel of the Forgotten Kingdom (Nord-Pailune): Banditen ausschalten, Steinlaterne anzünden öffnet die Zelle → Steinsarg."},
  {name:"Howling Hill Camp",region:"Hernand",type:"Camp / Hub",desc:"Graumähnen-Basis südlich der Stadt Hernand. Camp-Schmiede, Stable, Dispatch-System, Privatlager (240–640 Slots). Ausbau in 4 Stufen, danach optionaler Umzug nach Pailune — Details auf der Seite Graumähnen-Camp."},
  {name:"Wayward Woods",region:"Pailune (SW)",type:"Witch / Mount",desc:"Nebelwald am Fuß des Fünf-Finger-Bergs im Südwesten Pailunes. Auf einer Klippe liegt das Irrwald-Versteck der Hexe (Baumhaus in einem vom Blitz gespaltenen toten Baum) — laut Guides das Versteck der Hexe Weiße Krähe, erreichbar erst mit allen 4 Witch's Tokens (je eines von Elowen, Bari, Lyselia und Areciel), die in die Tür eingesetzt werden. Die ältere Angabe 'Stone Worm Cave (Gold-Farm)' ist nicht belegt. (Schwarzzahn/Silberzahn ist NICHT hier, sondern im Wolfswald, Hernand.)"},
  {name:"Witch's Hideout (Silver Wolf Mountain)",region:"Pailune (Silver Wolf Mountain)",type:"Witch Location",desc:"Höhle in den Wäldern der Silberwolfberg in Pailune; laut questlog-Wissenseintrag 'Hexenversteck' der Wohnort einer Hexe. Es gibt gelegentlich Berichte von Leuten, die ihr begegnet sein wollen, aber nicht jedem wird diese Chance zuteil: Sie erscheint nur jenen am Rande der Verzweiflung, kurz bevor sie ihre schlimmste Entscheidung treffen, und die Höhle selbst bleibt unsichtbar, solange sie nicht erscheinen will. Keiner der namentlich erfassten Hexen zugeordnet (Bari wohnt in einem Haus am Roten See derselben Berggegend, siehe Hexen & Fusion); Fundort und Freischaltung nicht erfasst."},
  {name:"Crimson Desert Witch's Hideout",region:"Crimson Desert (bei Urdavah)",type:"Witch Location",desc:"Haus auf halber Höhe einer Klippe nahe Urdavah (game8: westlich davon) — laut game8 und der Seite Hexen & Fusion das Versteck der Wüstenhexe Areciel (Hexe der Stärke). Sie zu treffen ist aus zwei Gründen schwierig: Von der Sonne geblendete Reisende schauen selten nach oben, und der Weg zum Versteck ist ohne vorheriges Training praktisch unmöglich. Freischaltung der Hexe: 1 Kupfer an den bettelnden Jungen am Bounty Board an der Straße nördlich von Tommaso."},
  {name:"Wayward Woods Witch's Hideout",region:"Pailune (Wayward Woods)",type:"Witch Location",desc:"Baumhaus auf einer Klippe in den Irrwald westlich von Pailune: das Heim einer Hexe in einem toten, vom Blitz gespaltenen Baum, schwer zu finden, weil man den Irrwald durchqueren und die Klippen überwinden muss. Laut game8 das Versteck der Weißen Krähe; Zugang erst nach allen vier Hexen-Questlinien mit den vier Witch's Tokens, die in die Tür eingesetzt werden (siehe Irrwald und Hexen & Fusion)."},
  {name:"Sanctum of Benediction",region:"Hernand (SW Everfrost)",type:"Sanctum",desc:"Tief im Winterberg-Gebirge im Südwesten (game8; Fextralife führt Winterberg unter Hernand). Reinigung setzt die Quest der Witch of Wisdom (Elowen) voraus. Lederkopfbedeckung des gefallenen Königreichs (mit Momentum-Core) — fertiges Item aus einer Truhe im versteckten Raum (Geheimtür über die Laterne neben der verdächtigen Wand), KEINE Blaupause."},
  {name:"Ascetic's Rest",region:"The Abyss",type:"Abyss",desc:"Abyss-Bereich (laut questlog ein Abyss-Tor). Das Knowledge 'Asketenruh' gibt es in den Missionsschritten 'Visit Master Du', 'Assess the situation with your comrades' und 'Stelle den Abyss wieder her' — dieselben Schritte belohnen laut questlog die normale Palmar-Pill-Formel. Der kursierende Fundort der Refined-Palmar-Pill-Formel hier (nach Kap. 9, 'Sechs nachdenkliche Statuen und der böse Geist') ist unbelegt; die Refined-Formel ist Belohnung der Mission 'Raccos Anfrage'."},
  {name:"Pororin Village",region:"Hernand (Pororin Forest, östlich/südöstlich)",type:"Faction",desc:"Abgeschiedenes Dorf der Shai und Fadu. Fraktion Wächter des Pororin-Walds — laut PowerPyx gehört die Glocken-Questreihe ('Glockenläuten auf dem Kontinent von Pywel', Guides: 'Toll of Pywel', 8 Glocken) zu dieser Fraktion. Geheimladen mit Amulett der Tapferkeit (Haustier-Hunde greifen an; offizielle Notes 1.06.00). Eine Quest 'Pharmacological Research' als Palmar-Pill-Quelle ist nicht belegt (Formel: siehe Schattenflüsterhöhle)."},
  {name:"Lioncrest Watchtower",region:"Hernand",type:"Quest Item",desc:"Visione-Helm (oberstes Stockwerk) — Quest Erinnerungsfragment, Kap. 2."},
  {name:"Silverbrook Ruins",region:"Delesyia (N)",type:"Unique Weapon",desc:"Messingrosenrapier — unterste Ebene eines kleinen Turms (frei aufsammelbar, nicht verpassbar)."},
  {name:"Marni's Masterium",region:"Delesyia",type:"Boss",desc:"Goldener Stern Mecha-Drache (Kap. 11). Marni-Spear-Pylons an Arenarand."},
  {name:"Kilnden Workshop",region:"Hernand",type:"Crafting Station",desc:"Werkstatt der Zwerge um Grimnir, ab Kap. 4 (Quests 'Kilnden-Werkstatt', 'Kiln Repair at the Kilnden Workshop' und 'Der geheimnisvolle Topf', mit der die Kuku-Werkstatt freigeschaltet wird). Kuku-Werkstatt: Ausbau des Kuku-Eisentopfs mit Sanktum-Cores bei Grimnir (game8) sowie Kuku-Gadgets und -Ausrüstung (Kuku-Speer, Kuku-Rucksack, Kuku-Resistenzrüstungen u. a.)."},
  {name:"Hexe Sanctuary",region:"Demeniss",type:"Boss",desc:"Hexe Marie (Kap. 9, Quest 'Verschleierte Hexe'). In der Mission 'Jagd jenseits des Schleiers' vier Steintotems zerstören, um den Schleier zu lösen; danach Bosskampf (Mission 'Schwarze Hexe')."},
  {name:"Howling Hollow Cave",region:"Hernand",type:"Mount",desc:"Höhle, in questlog als 'Heulende Höhle' geführt. Hier das Tier Silberzahn erlegen + SOFORT häuten → 'Zahn des Silberzahns' → Sigil bei Elowen = Silberzahn-Mount. Der Black-Fang-Boss (Haus Celeste) wird zuvor im Wolfswald bekämpft, NICHT hier."},
  {name:"Bordig Ruins",region:"Crimson Desert",type:"Boss / Mount",desc:"Ruinen am Beginn des Regenwalds an der Grenze zur Crimson Desert. Wilder Reißer Ravok (Quest 'Wilder Reißer', Mission 'Herrscher der Sümpfe') kämpft im Sumpfgebiet südlich der Votudig-Ruinen (südliches Tashkalp, westlich des Roten Flusses) → Steinhauer-Warzenschwein-Mount."},
  {name:"Ashclaw Keep",region:"Pailune",type:"Boss",desc:"Black-Bear-Festung im Herzen eines aktiven Vulkankraters — laut questlog eine uneinnehmbare Bastion, die das raue Vulkangelände nutzt; jede bisherige Expedition gegen sie wurde zurückgeschlagen. Myurdin + Lava-Myurdin Boss-Fight (Kap. 7, Hauptquest-Mission 'Schlacht am Silberwolfberg'). Oongka wird danach in der Story-Mission 'Unvollendeter Sieg' erstmals spielbar; dass das am Aschenklaue-Bergfried selbst geschieht, ist nicht belegt."},
  {name:"Spire of Ringing Truth",region:"Pailune",type:"Boss / Skill",desc:"Spire in Skoghorn. Boss Priscus, der Älteste (Quest 'Priscus, der Älteste'), einer der drei Ancients; der Spire gehört laut questlog zu den Orten des Schritts 'Cleanse the cores that are binding Aeserion'. Zugang zum Boss laut Fextralife: an der Spitze die Stütze der großen Glocke abschießen. Danach öffnet sich über ein Abyss-Tor ein Abyss-Gebiet: Die Abyss-Challenges Ether Rest, Bitteres Paradies und Pfad der Prüfungen (laut questlog Teil der Quest 'Abyss') schalten das Element Frost (Lv. 1) und damit Bitterer Mantel und Frost als Element-Imbue frei (Fextralife, thegameswiki)."},
  {name:"Thornbriar Fortress",region:"Demeniss",type:"Boss / Story",desc:"Burg von Herzog Wells (deutsch „Dornwallfestung“); das Gebiet des Hauses Wells (Wells-Ländereien) liegt laut Spieltext in Süd-Demeniss. Laut Spieltext eine natürliche Festung mit Wassergraben, Mauern und Küstenklippen. Kap. 8 (Quest Nach Demeniss): Großschlacht (Mission 'Unterdrückung der Rebellen', in der Kapitelübersicht 'Rebel Suppression'), Boss Fortain, der fluchgebundene Ritter (Mission 'Der verfluchte Ritter'), danach Treffen mit Herzog Wells (Mission 'Besitzer der Dornwallfestung'). Patch 2.02.00 behob einen Fehler, durch den sich die Festung nicht befreien ließ."},
  {name:"The Laughing Marionette",region:"Demeniss",type:"Minigame [1.06]",desc:"Greifautomat, bezahlt wird mit Silber; der Preis pro Versuch ist nicht belegt (die offiziellen Patch Notes nennen ihn nicht). Belohnungen: 12 Beleuchtungsitems, 1 Stuhl, 1 Spezial-Kopfbedeckung, Abyss Artefakte, Blaupausen für Abyss-Teile."},
  {name:"Smithy (Extraction)",region:"Alle Regionen",type:"Crafting [1.06]",desc:"Neues Extraction-System: Materialien aus verfeinerter Ausrüstung zurückgewinnen. Seltenere Materialien (Artefakte, Aeserions Schuppe) zu 100% zurück, Basis-Materialien (Erz, Blutgestein) ~70%. Rückbau wahlweise um eine Stufe oder ganz bis zur Basis-Verfeinerungsstufe (Stufe beim Erhalt des Items); das Item bleibt erhalten. Nutzbar an Schmieden in verschiedenen Regionen."},
  {name:"Oongka — Unbewaffnete Skills",region:"Überall",type:"Feature [1.06]",desc:"Oongka hat Faustkampf-Fähigkeiten. Im Skill-Menü 'Fäuste' auswählen. Damiane erhielt eigene Fäuste-Fähigkeiten in Patch 1.07."},
  {name:"Weapon Sheaths",region:"Einstellungen",type:"Feature [1.06]",desc:"Schwertscheide am Charakter an/aus schaltbar: Einstellungen → 'Display Sheath' Option."},
  {name:"Night Tone Mode",region:"Einstellungen",type:"Feature [1.06]",desc:"Neue Grafik-Option: Night Tone Mode dämpft Gesamtfarben und hellt Schattenbereiche auf. Deaktiviert = kräftigere, kontrastreichere Farben."},
  {name:"Damiane — Unbewaffnete Skills",region:"Überall",type:"Feature [1.07]",desc:"Unbewaffnete Kampf-Fähigkeiten für Damiane (Skill-Menü → 'Fäuste'); dazu verbesserte allgemeine Bewegungsanimation im unbewaffneten Kampf. Oongka erhielt seine Fäuste-Fähigkeiten bereits in 1.06."},
  {name:"Damiane/Oongka — Aerial Stab",region:"Skill-Tree",type:"Feature [1.07]",desc:"Neuer Skill 'Sprungstoß' für Damiane und Oongka (offizielle Notes 1.07.00: Luft-Mobilität wie bei Kliff). Laut questlog: In der Luft die Stoß-Taste drücken → Stoß nach vorn; bei wiederholtem Einsatz steigt der Ausdauer-Verbrauch. Kliffs Sprungstoß ist eine Untervariante von Stab (Stab Lv 3)."},
  {name:"Oongka — Explosive Strike: Charge-Phase",region:"Skill-Tree",type:"Feature [1.07]",desc:"Explosionsschlag hat jetzt eine Charge-Phase (Aufladen); ob Aufladen Schaden oder Wirkungsbereich erhöht, nennen die offiziellen Notes nicht. Laut questlog-Skillbeschreibung (Explosionsschlag, 20076) lassen sich bis zu 30 zusätzliche Geist für einen stärkeren Schlag aufwenden; ob das die Charge-Phase der Notes meint, ist nicht belegt. Beim Dual-Wield lässt sich besser in 'Stab' übergehen."},
  {name:"Kliff — Blinding Flash Finisher (unarmed)",region:"Skill-Tree",type:"Feature [1.07]",desc:"Neu: 'Sturmhieb' für den unbewaffneten Kampf (offizielle Notes 1.07.00). Ergänzt die Änderung aus 1.06.00, mit der 'Licht reflektieren' auch ohne ausgerüstete Waffe nutzbar wurde."},
  {name:"Rematch — Muskan",region:"Bonepit",type:"Boss-Rematch [1.07]",desc:"Muskan (Boss der Bonepit, Crimson Desert) ist an der Bonepit via Laterne rematchbar. Erinnerungsfragment am Kampfort; Reminisce-/Resonate-Modi wie beim Rematch-System aus 1.05.00. Die Rematch-Orte zeigt das Spiel unter Tagebuch > Knowledge > Erinnerungsfragment > Bosses."},
  {name:"Rematch — Corrupted Caliburn",region:"Fort Musket",type:"Boss-Rematch [1.07]",desc:"Verdorbener Caliburn (Kap. 12 Endboss-Phase) ist jetzt bei der Festung Muskete via Laterne rematchbar — kein 2. Spieldurchgang nötig. [1.13.00: Erinnerungsfragment-Fundort im Zuge der Abyss-Öffnung verlegt — der genannte Ort galt bis Patch 1.12; den neuen Ort nennen die offiziellen 1.13-Notes bewusst nicht (Spoiler), kein Guide hat ihn dokumentiert. Praxis-Tipp: aktuellen Fundort selbst im Spiel prüfen via Tagebuch > Knowledge > Erinnerungsfragment > Bosses (zeigt pro besiegtem Boss den aktuellen Rematch-Ort); nicht auf Prä-1.13-Angaben (Festung Muskete) verlassen. Dort nicht mehr suchen.]"},
  {name:"Rematch — Goyen",region:"Spire of the Sun",type:"Boss-Rematch [1.07]",desc:"Goyen-Rematch an der Spitze der Sonne via Laterne. Vorher nur einmaliger Story-Kill. [1.13.00: Erinnerungsfragment-Fundort im Zuge der Abyss-Öffnung verlegt — der genannte Ort galt bis Patch 1.12; den neuen Ort nennen die offiziellen 1.13-Notes bewusst nicht (Spoiler), kein Guide hat ihn dokumentiert. Praxis-Tipp: aktuellen Fundort selbst im Spiel prüfen via Tagebuch > Knowledge > Erinnerungsfragment > Bosses (zeigt pro besiegtem Boss den aktuellen Rematch-Ort); nicht auf Prä-1.13-Angaben (Spitze der Sonne) verlassen. Dort nicht mehr suchen.]"},
  {name:"Rematch — Draven the Crowcaller",region:"Church of West Demeniss",type:"Boss-Rematch [1.07]",desc:"Draven-Rematch in der Kirche von West-Demeniss via Laterne (ursprünglicher Kampfort: Krähennest im Abyss; laut offiziellen Notes wurden die Rematch-Orte von Abyss-Bossen an Land verlegt). Ob der Rematch erneut Beute gibt, ist nicht belegt. [1.13.00: Erinnerungsfragment-Fundort im Zuge der Abyss-Öffnung verlegt — der genannte Ort galt bis Patch 1.12; den neuen Ort nennen die offiziellen 1.13-Notes bewusst nicht (Spoiler), kein Guide hat ihn dokumentiert. Praxis-Tipp: aktuellen Fundort selbst im Spiel prüfen via Tagebuch > Knowledge > Erinnerungsfragment > Bosses (zeigt pro besiegtem Boss den aktuellen Rematch-Ort); nicht auf Prä-1.13-Angaben (Kirche von West-Demeniss) verlassen. Dort nicht mehr suchen.]"},
  {name:"Rematch — Clockwork White Horn",region:"Gate to Advancement",type:"Boss-Rematch [1.07]",desc:"Uhrwerk-Weißhorn (ursprünglich im Abyss: Uhrwerk-Herz, Ewiger Korridor) ist jetzt am Tor der Technologie via Laterne rematchbar. [1.13.00: Erinnerungsfragment-Fundort im Zuge der Abyss-Öffnung verlegt — der genannte Ort galt bis Patch 1.12; den neuen Ort nennen die offiziellen 1.13-Notes bewusst nicht (Spoiler), kein Guide hat ihn dokumentiert. Praxis-Tipp: aktuellen Fundort selbst im Spiel prüfen via Tagebuch > Knowledge > Erinnerungsfragment > Bosses (zeigt pro besiegtem Boss den aktuellen Rematch-Ort); nicht auf Prä-1.13-Angaben (Tor der Technologie) verlassen. Dort nicht mehr suchen.]"},
  {name:"Mehr Wolf-/Bär-Mounts",region:"Wild",type:"Feature [1.07]",desc:"Zusätzliche Wolf- und Bär-Typen können jetzt als Mounts registriert werden. Dazu Zügel für bestimmte Mounts; insgesamt mehr Tiere in der Welt als Mount nutzbar."},
  {name:"AMD GPU Crash-Fix",region:"PC-Performance",type:"Fix [1.07]",desc:"GPU-Crash mit AMD-Treiber 26.5.1 behoben (offizielle Notes). Downloadgröße 381 MB (Steam, laut VULKK) und Konsolen-Build 1.000.283 (laut MP1st) sind nicht offiziell."}
];
